import { c } from 'ttag';

import { process } from '@proton/components/containers/payments/paymentTokenHelper';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';

let tab: { closed: boolean; close: () => any };

function delay(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

beforeEach(() => {
    jest.clearAllMocks();

    tab = { closed: false, close: jest.fn() };
    jest.spyOn(window, 'open').mockReturnValue(tab as any);
    jest.spyOn(window, 'removeEventListener');
    jest.spyOn(window, 'addEventListener');
});

describe('process', () => {
    let ApprovalURL = 'https://example.proton.me';
    let ReturnHost = 'https://return.proton.me';
    let Token = 'some-payment-token-222';
    let api: jest.Mock;
    let signal: AbortSignal;

    beforeEach(() => {
        api = jest.fn();
        signal = {
            aborted: false,
            reason: null,
            onabort: jest.fn(),
            throwIfAborted: jest.fn(),
            addEventListener: jest.fn(),
            removeEventListener: jest.fn(),
            dispatchEvent: jest.fn(),
        };
    });

    it('should open the ApprovalURL', () => {
        tab.closed = true; // prevents the test from hanging because of an unhandled promise
        process({ api, ApprovalURL, ReturnHost, signal, Token }).catch(() => {});

        expect(window.open).toHaveBeenCalledWith(ApprovalURL);
    });

    it('should add abort listener to the signal', async () => {
        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        expect(signal.addEventListener).toHaveBeenCalledTimes(1);
        const signalAddEventListenerMock = signal.addEventListener as jest.Mock;
        expect(signalAddEventListenerMock.mock.lastCall[0]).toEqual('abort');
        expect(typeof signalAddEventListenerMock.mock.lastCall[1]).toBe('function');

        expect(window.addEventListener).toHaveBeenCalledTimes(1);
        const windowAddEventListenerMock = window.addEventListener as jest.Mock;
        expect(windowAddEventListenerMock.mock.lastCall[0]).toEqual('message');
        expect(typeof windowAddEventListenerMock.mock.lastCall[1]).toEqual('function');
        const onMessage = windowAddEventListenerMock.mock.lastCall[1];

        const abort = signalAddEventListenerMock.mock.lastCall[1];

        abort();

        expect(window.removeEventListener).toHaveBeenCalledWith('message', onMessage, false);
        expect(signal.removeEventListener).toHaveBeenCalledWith('abort', abort);
        expect(tab.close).toHaveBeenCalled();
        await expect(promise).rejects.toEqual(new Error(c('Error').t`Process aborted`));
    });

    it('should resolve if Status is STATUS_CHARGEABLE', async () => {
        tab.closed = true;
        api.mockResolvedValue({
            Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE,
        });

        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        await expect(promise).resolves.toEqual(undefined);
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_PENDING,
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('should reject if Status is %s', async (Status) => {
        tab.closed = true;
        api.mockResolvedValue({
            Status,
        });

        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token });

        await expect(promise).rejects.toEqual({ tryAgain: true });
    });

    it('should re-try to confirm until the tab is closed', async () => {
        api.mockResolvedValue({
            Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE,
        });

        const delayListening = 10;
        const promise = process({ api, ApprovalURL, ReturnHost, signal, Token }, delayListening);
        await delay(delayListening * 5);

        tab.closed = true;

        await expect(promise).resolves.toEqual(undefined);
    });
});

import PropTypes from 'prop-types';
import { c } from 'ttag';

import { checkInvoice, payInvoice } from '@proton/shared/lib/api/payments';
import { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';
import { toPrice } from '@proton/shared/lib/helpers/string';
import { Currency } from '@proton/shared/lib/interfaces';

import { Field, FormModal, Input, Label, Price, PrimaryButton, Row } from '../../components';
import { useApi, useApiResult, useEventManager, useLoading, useModals, useNotifications } from '../../hooks';
import Payment from '../payments/Payment';
import StyledPayPalButton from '../payments/StyledPayPalButton';
import { AmountAndCurrency, ExistingPayment, TokenPaymentMethod, WrappedCardPayment } from '../payments/interface';
import { createPaymentToken } from '../payments/paymentTokenHelper';
import usePayment from '../payments/usePayment';
import { Invoice } from './interface';

interface CheckInvoiceResponse {
    Code: number;
    Currency: Currency;
    Amount: number;
    Gift: number;
    Credit: number;
    AmountDue: number;
}

export interface Props {
    invoice: Invoice;
    fetchInvoices: () => void;
    onClose?: () => void;
}

const PayInvoiceModal = ({ invoice, fetchInvoices, ...rest }: Props) => {
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const { call } = useEventManager();
    const api = useApi();
    const { result, loading: isLoading } = useApiResult<CheckInvoiceResponse, typeof checkInvoice>(
        () => checkInvoice(invoice.ID),
        []
    );

    const { AmountDue, Amount, Currency, Credit } = result ?? {};

    /**
     * @param params must be null if user pays from the credit balance.
     */
    const handleSubmit = async (params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment | null) => {
        const amountAndCurrency: AmountAndCurrency = { Amount: AmountDue as number, Currency: Currency as Currency };

        let payInvoiceData: (TokenPaymentMethod & AmountAndCurrency) | AmountAndCurrency = {
            ...amountAndCurrency,
        };

        if (params) {
            let paymentToken = await createPaymentToken(
                {
                    params,
                    api,
                    createModal,
                },
                amountAndCurrency
            );

            payInvoiceData = { ...payInvoiceData, ...paymentToken };
        }

        await api(payInvoice(invoice.ID, payInvoiceData));
        await Promise.all([
            call(), // Update user.Delinquent to hide TopBanner
            fetchInvoices(),
        ]);
        rest.onClose?.();
        createNotification({ text: c('Success').t`Invoice paid` });
    };

    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =
        usePayment({
            amount: AmountDue as number,
            currency: Currency as Currency,
            onPaypalPay: handleSubmit,
        });

    const submit =
        method === PAYMENT_METHOD_TYPES.PAYPAL ? (
            <StyledPayPalButton paypal={paypal} flow="invoice" amount={AmountDue ?? 0} />
        ) : (
            <PrimaryButton loading={loading} disabled={!canPay} type="submit">{c('Action').t`Pay`}</PrimaryButton>
        );

    return (
        <FormModal
            onSubmit={() => {
                if (!handleCardSubmit()) {
                    return;
                }

                withLoading(handleSubmit(parameters));
            }}
            loading={loading}
            close={c('Action').t`Close`}
            submit={submit}
            title={c('Title').t`Pay invoice`}
            {...rest}
        >
            {!isLoading && (
                <>
                    {!!Credit && (
                        <>
                            <Row>
                                <Label>{c('Label').t`Amount`}</Label>
                                <Field className="text-right">
                                    <Price className="label" currency={Currency}>
                                        {Amount ?? 0}
                                    </Price>
                                </Field>
                            </Row>
                            <Row>
                                <Label>{c('Label').t`Credits used`}</Label>
                                <Field className="text-right">
                                    <Price className="label" currency={Currency}>
